// Phase 1 harness: prove the transport / parse / stream pipeline end to end.
// The HAAS pendant replaces all of this in phase 2 — only the wiring below the UI
// (transport selection, status polling, streamer ownership) survives.

import { websocketTransport, serialTransport, simTransport } from './transport.js'
import { parseStatus, parseFeedback, rxBufferFromOpt, Streamer, prepare, describeAlarm } from './grbl.js'

const $ = (id) => document.getElementById(id)
const STATUS_IDLE_MS = 500     // poll `?` only when the board has gone quiet

let link = null
let streamer = null
let program = []
let lastReportAt = 0
let pollTimer = null

// ------------------------------------------------------------------ console log

function log (text, cls = 'rx') {
  const el = $('log')
  const atBottom = el.scrollHeight - el.scrollTop - el.clientHeight < 40
  const div = document.createElement('div')
  div.className = cls
  div.textContent = text
  el.appendChild(div)
  while (el.childElementCount > 500) el.firstElementChild.remove()
  if (atBottom) el.scrollTop = el.scrollHeight
}

// --------------------------------------------------------------------- machine

const machine = { mpos: [0, 0, 0, 0], wco: [0, 0, 0, 0], state: '—' }

function applyStatus (s) {
  lastReportAt = performance.now()
  machine.state = s.sub === null ? s.state : `${s.state}:${s.sub}`
  if (s.MPos) machine.mpos = s.MPos
  if (s.WCO) machine.wco = s.WCO

  $('state').textContent = machine.state
  for (let i = 0; i < 4; i++) {
    $('m' + i).textContent = machine.mpos[i]?.toFixed(3) ?? '—'
    $('w' + i).textContent = (machine.mpos[i] - machine.wco[i]).toFixed(3)
  }
  if (s.feed !== undefined) $('feed').textContent = s.feed
  if (s.spindle !== undefined) $('rpm').textContent = s.spindle
  if (s.bf) $('buf').textContent = `${s.bf.blocks}/${s.bf.bytes}`
  if (s.line !== undefined) $('ln').textContent = s.line
}

function onLine (line) {
  const status = parseStatus(line)
  if (status) { applyStatus(status); return }

  // The streamer consumes its own acknowledgements; anything else is for the human.
  if (streamer?.onLine(line)) {
    updateProgress()
    if (streamer.error) {
      log(`error:${streamer.error.code} at line ${streamer.error.line} — ${streamer.error.text}`, 'err')
      setRunning(false)
    } else if (streamer.done) {
      log('[job complete]', 'tx')
      setRunning(false)
    }
    return
  }

  if (line.startsWith('ALARM:')) {
    log(`${line} — ${describeAlarm(Number(line.slice(6)))}`, 'err')
    setRunning(false)
    return
  }
  if (line.startsWith('error:')) { log(line, 'err'); return }

  const fb = parseFeedback(line)
  if (fb?.kind === 'OPT') {
    const rx = rxBufferFromOpt(fb.value)
    if (rx && streamer) {
      streamer.rxBuffer = rx
      log(`[rx buffer: ${rx} bytes, from the board]`, 'tx')
    }
  }
  log(line)
}

// ------------------------------------------------------------------ connection

async function connect () {
  const kind = $('kind').value
  try {
    link = kind === 'websocket' ? websocketTransport({ host: $('host').value })
      : kind === 'serial' ? serialTransport()
        : simTransport()

    link.onLine(onLine)
    await link.connect()

    streamer = new Streamer(wire => { link.send(wire) }, 128)
    lastReportAt = 0
    pollTimer = setInterval(pollIfQuiet, 200)

    $('link').textContent = `connected — ${link.describe()}`
    $('connect').disabled = true
    for (const id of ['run', 'hold', 'resume', 'reset']) $(id).disabled = false

    // Ask once for identity so we can size the streamer's buffer from the board
    // rather than trusting the conservative default.
    link.send('$I\n')
  } catch (e) {
    log(`[connect failed: ${e.message}]`, 'err')
    link = null
  }
}

/**
 * One status rule for all three transports: the ClearCore pushes reports every
 * 250 ms on its own ($397=250), so this timer never fires there; over serial it
 * becomes a 5 Hz poll. No per-transport special-casing.
 */
function pollIfQuiet () {
  if (!link) return
  if (performance.now() - lastReportAt > STATUS_IDLE_MS) link.sendRealtime(0x3F)
}

// ------------------------------------------------------------------------ job

function setRunning (on) {
  $('run').disabled = on || !link
  $('file').disabled = on
}

function updateProgress () {
  if (!streamer?.total) return
  $('prog').value = streamer.acked / streamer.total
  $('progtext').textContent = `${streamer.acked} / ${streamer.total}`
}

$('file').onchange = async (e) => {
  const f = e.target.files[0]
  if (!f) return
  program = prepare(await f.text())
  $('progtext').textContent = `${program.length} lines ready`
  log(`[loaded ${f.name}: ${program.length} lines]`, 'tx')
}

$('run').onclick = () => {
  if (!program.length) return log('[no program loaded]', 'err')
  setRunning(true)
  streamer.start(program.map(l => l.text))
  updateProgress()
}
$('hold').onclick = () => link?.sendRealtime(0x21)
$('resume').onclick = () => link?.sendRealtime(0x7E)
$('reset').onclick = () => {
  link?.sendRealtime(0x18)
  streamer?.stop()
  setRunning(false)
}

$('connect').onclick = connect
$('send').onclick = () => {
  const v = $('cmd').value.trim()
  if (!v || !link) return
  log('> ' + v, 'tx')
  link.send(v + '\n')
  $('cmd').value = ''
}
$('cmd').onkeydown = (e) => { if (e.key === 'Enter') $('send').click() }

addEventListener('beforeunload', () => { clearInterval(pollTimer); link?.disconnect() })

