input.content:
/* HAAS pendant chrome.
   Colours sampled from figure F2.26 of the 2014 Mill Operator's Manual rather than
   guessed: the greys, the cyan, the RESET orange and the yellow accent are the
   values that appear in the manual artwork. */

:root {
  /* palette, straight off the artwork */
  --bezel:        #cccbcb;
  --panel-black:  #231f20;
  --cyan:         #0090c2;
  --key-hi:       #e9e9e9;
  --key-face:     #bdbcbc;
  --key-mid:      #a7a5a6;
  --key-lo:       #918f8f;
  --key-edge:     #7b7979;
  --reset-hi:     #f47216;
  --reset-lo:     #d55415;
  --reset-edge:   #61090b;
  --yellow:       #ffd200;
  --yellow-deep:  #f9af15;

  /* the classic screen */
  --screen-bg:    #0d3b1e;
  --screen-pane:  #14522a;
  --screen-text:  #e8f6e8;
  --screen-dim:   #8fc79b;
  --screen-key:   #ffe680;
  --screen-active:#ffffff;
  --screen-alarm: #c8102e;

  /* one unit drives every dimension, so the pendant scales as a whole */
  --u: clamp(6px, 0.78vw, 11px);

  --key-r: calc(var(--u) * 0.55);
  --font-key: "Arial Narrow", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --font-screen: ui-monospace, "DejaVu Sans Mono", "Liberation Mono", monospace;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #21252a;
  font-family: var(--font-key);
  -webkit-font-smoothing: antialiased;
}

/* ---------------------------------------------------------------- the pendant */

.pendant {
  display: grid;
  grid-template-columns: calc(var(--u) * 20) 1fr;
  gap: calc(var(--u) * 1.5);
  padding: calc(var(--u) * 1.6);
  border-radius: calc(var(--u) * 0.6);
  /* brushed stainless */
  background:
    repeating-linear-gradient(90deg,
      rgba(255,255,255,.055) 0 1px, rgba(0,0,0,.05) 1px 2px, transparent 2px 4px),
    linear-gradient(160deg, #d9dde0, #b8bec3 45%, #cdd2d6 70%, #aeb4b9);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.7),
    inset 0 -2px 6px rgba(0,0,0,.28),
    0 calc(var(--u) * 1.2) calc(var(--u) * 3) rgba(0,0,0,.55);
}

/* screws in the corners, as on the real panel */
.pendant::before, .pendant::after {
  content: ""; position: absolute; width: calc(var(--u) * .9); height: calc(var(--u) * .9);
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #eceff1, #7d858c 60%, #5c6368);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.35);
}
.pendant { position: relative; }
.pendant::before { top: calc(var(--u) * .55); left: calc(var(--u) * .55); }
.pendant::after  { top: calc(var(--u) * .55); right: calc(var(--u) * .55); }

/* ------------------------------------------------------------- left-hand column */

.column {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--u) * 1.1);
  padding-top: calc(var(--u) * 1.4);
}

.logo {
  width: calc(var(--u) * 9); height: calc(var(--u) * 9);
  border-radius: 50%;
  display: grid; place-items: center;
  background: radial-gradient(circle at 38% 30%, #f2f4f5, #9aa1a7 55%, #6e757b);
  box-shadow: inset 0 0 0 calc(var(--u)*.22) #babfc4, 0 2px 5px rgba(0,0,0,.45);
}
.logo svg { width: 78%; height: 78%; }

.legend {
  font-size: calc(var(--u) * .82);
  letter-spacing: .06em;
  color: #23282c;
  text-align: center;
  font-weight: 700;
}

.pair { display: flex; gap: calc(var(--u) * 2.2); }
.pair > div { display: flex; flex-direction: column; align-items: center; gap: calc(var(--u)*.4); }

/* round illuminated pushbuttons */
.pb {
  width: calc(var(--u) * 3.4); height: calc(var(--u) * 3.4);
  border-radius: 50%; border: none; cursor: pointer;
  box-shadow: inset 0 calc(var(--u)*.18) 0 rgba(255,255,255,.55),
              inset 0 calc(var(--u)*-.25) calc(var(--u)*.3) rgba(0,0,0,.4),
              0 calc(var(--u)*.2) calc(var(--u)*.4) rgba(0,0,0,.45);
}
.pb:active { transform: translateY(1px); filter: brightness(1.25); }
.pb.green { background: radial-gradient(circle at 38% 32%, #7ee89a, #1f9c46 60%, #12703200); background-color: #1f9c46; }
.pb.red   { background: radial-gradient(circle at 38% 32%, #ff9a90, #c0281c 60%, #8b160e00); background-color: #c0281c; }

/* emergency stop */
.estop {
  width: calc(var(--u) * 8); height: calc(var(--u) * 8);
  border-radius: 50%; border: none; cursor: pointer; position: relative;
  background: radial-gradient(circle at 50% 45%, #ffe14d, #f2c200 62%, #c99e00);
  box-shadow: 0 calc(var(--u)*.3) calc(var(--u)*.6) rgba(0,0,0,.5);
  display: grid; place-items: center;
}
.estop i {
  display: block; width: 66%; height: 66%; border-radius: 50%;
  background: radial-gradient(circle at 42% 34%, #ff6a5a, #c8102e 62%, #8c0a1f);
  box-shadow: inset 0 calc(var(--u)*-.3) calc(var(--u)*.4) rgba(0,0,0,.45),
              inset 0 calc(var(--u)*.2) 0 rgba(255,255,255,.3);
}
.estop:active i { filter: brightness(.85); }

/* handle-jog dial */
.dial {
  width: calc(var(--u) * 9.5); height: calc(var(--u) * 9.5);
  border-radius: 50%; position: relative; cursor: grab;
  background: conic-gradient(from 0deg, #d7dbde, #aeb4b9 12%, #d7dbde 25%, #aeb4b9 37%,
              #d7dbde 50%, #aeb4b9 62%, #d7dbde 75%, #aeb4b9 87%, #d7dbde);
  box-shadow: inset 0 0 0 calc(var(--u)*.35) #9aa1a7, 0 calc(var(--u)*.25) calc(var(--u)*.5) rgba(0,0,0,.45);
  display: grid; place-items: center;
}
.dial:active { cursor: grabbing; }
.dial i {
  width: 52%; height: 52%; border-radius: 50%;
  background: radial-gradient(circle at 38% 30%, #f2f4f5, #9aa1a7 62%, #767d83);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.25);
  display: grid; place-items: center;
}
.dial i::after {   /* the knurl mark, so rotation is legible */
  content: ""; width: calc(var(--u)*.5); height: calc(var(--u)*.5); border-radius: 50%;
  background: #5c6368; transform: translateY(calc(var(--u) * -1.7));
}

/* ------------------------------------------------------------------ right side */

.stack { display: flex; flex-direction: column; gap: calc(var(--u) * 1.2); min-width: 0; }

/* ---------------------------------------------------------------- the keyboard */

.keyboard {
  background: var(--bezel);
