   Colours sampled from figure F2.26 of the 2014 Mill Operator's Manual rather than
   guessed: the greys, the cyan, the RESET orange and the yellow accent are the
   values that appear in the manual artwork. */

:root {
  /* palette, straight off the artwork */
  --bezel:        #cccbcb;
  --panel-black:  #231f20;
  --cyan:         #0090c2;
  --key-hi:       #e9e9e9;
  --key-face:     #bdbcbc;
  --key-mid:      #a7a5a6;
  --key-lo:       #918f8f;
  --key-edge:     #7b7979;
  --reset-hi:     #f47216;
  --reset-lo:     #d55415;
  --reset-edge:   #61090b;
  --yellow:       #ffd200;
  --yellow-deep:  #f9af15;

  /* the classic screen */
  --screen-bg:    #0d3b1e;
  --screen-pane:  #14522a;
  --screen-text:  #e8f6e8;
  --screen-dim:   #8fc79b;
  --screen-key:   #ffe680;
  --screen-active:#ffffff;
  --screen-alarm: #c8102e;

  /* one unit drives every dimension, so the pendant scales as a whole */
  --u: clamp(6px, 0.78vw, 11px);

  --key-r: calc(var(--u) * 0.55);
  --font-key: "Arial Narrow", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --font-screen: ui-monospace, "DejaVu Sans Mono", "Liberation Mono", monospace;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #21252a;
  font-family: var(--font-key);
  -webkit-font-smoothing: antialiased;
}

/* ---------------------------------------------------------------- the pendant */

.pendant {
  display: grid;
  grid-template-columns: calc(var(--u) * 20) 1fr;
  gap: calc(var(--u) * 1.5);
  padding: calc(var(--u) * 1.6);
  border-radius: calc(var(--u) * 0.6);
  /* brushed stainless */
  background:
    repeating-linear-gradient(90deg,
      rgba(255,255,255,.055) 0 1px, rgba(0,0,0,.05) 1px 2px, transparent 2px 4px),
    linear-gradient(160deg, #d9dde0, #b8bec3 45%, #cdd2d6 70%, #aeb4b9);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.7),
    inset 0 -2px 6px rgba(0,0,0,.28),
    0 calc(var(--u) * 1.2) calc(var(--u) * 3) rgba(0,0,0,.55);
}

/* screws in the corners, as on the real panel */
.pendant::before, .pendant::after {
  content: ""; position: absolute; width: calc(var(--u) * .9); height: calc(var(--u) * .9);
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #eceff1, #7d858c 60%, #5c6368);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.35);
}
.pendant { position: relative; }
.pendant::before { top: calc(var(--u) * .55); left: calc(var(--u) * .55); }
.pendant::after  { top: calc(var(--u) * .55); right: calc(var(--u) * .55); }

/* ------------------------------------------------------------- left-hand column */

.column {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--u) * 1.1);
  padding-top: calc(var(--u) * 1.4);
}

.logo {
  width: calc(var(--u) * 9); height: calc(var(--u) * 9);
  border-radius: 50%;
  display: grid; place-items: center;
  background: radial-gradient(circle at 38% 30%, #f2f4f5, #9aa1a7 55%, #6e757b);
  box-shadow: inset 0 0 0 calc(var(--u)*.22) #babfc4, 0 2px 5px rgba(0,0,0,.45);
}
.logo svg { width: 78%; height: 78%; }

.legend {
  font-size: calc(var(--u) * .82);
  letter-spacing: .06em;
  color: #23282c;
  text-align: center;
  font-weight: 700;
}

.pair { display: flex; gap: calc(var(--u) * 2.2); }
