  background: var(--screen-pane);
  border-radius: calc(var(--u) * .2);
  padding: calc(var(--u) * .3) calc(var(--u) * .45);
  overflow: hidden;
  min-width: 0;
  display: flex; flex-direction: column;
}
.pane > h3 {
  margin: calc(var(--u) * -.3) calc(var(--u) * -.45) calc(var(--u) * .3);
  padding: calc(var(--u) * .16) calc(var(--u) * .45);
  background: #06210f;
  color: var(--screen-dim);
  font: inherit; font-size: calc(var(--u) * .85);
  letter-spacing: .08em;
}
.pane pre { margin: 0; font: inherit; white-space: pre; overflow: hidden; }

/* "The currently active pane has a white background. You can work with data in a
   pane only when that pane is active." — 2014 manual, 2.3.4 */
.pane.active { background: #f2f5f2; color: #10160f; }
.pane.active > h3 { background: #d5dbd5; color: #223226; }

.pane-modebar  { grid-area: modebar; }
.pane-program  { grid-area: program; }
.pane-codes    { grid-area: codes; }
.pane-tool     { grid-area: tool; }
.pane-coolant  { grid-area: coolant; }
.pane-main     { grid-area: main; }
.pane-spindle  { grid-area: spindle; }
.pane-position { grid-area: position; }
.pane-timers   { grid-area: timers; }
.pane-status   { grid-area: status; }
.pane-alarm    { grid-area: alarm; }
.pane-icons    { grid-area: icons; }
.pane-input    { grid-area: input; }

/* mode bar: mode on the left, active display function on the right */
.modebar {
  grid-area: modebar;
  display: flex; justify-content: space-between; align-items: center;
  background: linear-gradient(180deg, #3aa0d8, var(--cyan));
  color: #fff; font-weight: 700; letter-spacing: .12em;
  padding: calc(var(--u) * .22) calc(var(--u) * .6);
  border-radius: calc(var(--u) * .9);
}

.pane-alarm { background: #3a0d13; color: #ffd7dc; }
.pane-alarm.on { background: var(--screen-alarm); color: #fff; }

.dro { display: grid; grid-template-columns: auto repeat(4, 1fr); gap: 0 calc(var(--u)*.6); }
.dro b { color: var(--screen-dim); font-weight: 400; }
.dro span { text-align: right; font-variant-numeric: tabular-nums; }
.pane.active .dro b { color: #4d6b54; }

.k { color: var(--screen-key); }
.dim { color: var(--screen-dim); }
.pane.active .dim { color: #4d6b54; }
.pane.active .k { color: #7a5c00; }

/* the running block, highlighted from Ln: in the status report */
.cur { background: var(--screen-key); color: #10160f; }

