    } else if (streamer.done) {
      s.message = 'program complete'
    }
    return invalidate()
  }

  if (line.startsWith('ALARM:')) {
    const n = Number(line.slice(6))
    s.alarm = `ALARM ${n} — ${describeAlarm(n)}`
    return invalidate()
  }
  if (line.startsWith('error:')) {
    const n = Number(line.slice(6))
    s.message = `error ${n} — ${describeError(n)}`
    return invalidate()
