  if (!fb) { s.message = line; return invalidate() }

  if (fb.kind === 'OPT') {
    const rx = rxBufferFromOpt(fb.value)
    if (rx && streamer) streamer.rxBuffer = rx
  } else if (fb.kind === 'GC') {
    s.modal = fb.value
    s.units = /\bG20\b/.test(fb.value) ? 'IN' : 'MM'
    const wcs = fb.value.match(/G5[4-9](\.\d)?/)
    if (wcs) s.wcs = wcs[0]
  } else if (fb.kind === 'TLO') {
    s.tlo = fb.value[2] ?? 0
  } else if (fb.kind === 'MSG') {
    s.message = fb.value
  }
  invalidate()
}

function applyStatus (st) {
  lastReportAt = performance.now()
