const click = (k) => document.querySelector(`[data-key="${k}"]`).dispatchEvent(new PointerEvent('pointerdown', {bubbles:true}));
const dro = () => [...document.querySelectorAll('.pane-main .dro.big span')].slice(4,8).map(e=>e.textContent);
const bar = () => document.querySelector('.modebar').textContent.trim().replace(/\s+/g,' ');

const before = dro();

click('inc-01');                       // 10 mm increment in MM mode
click('jog-x-plus'); click('jog-x-plus');
click('jog-y-plus');
await new Promise(r=>setTimeout(r,1800));
const afterJog = dro();

click('mode-memory');  await new Promise(r=>setTimeout(r,120));
const memBar = bar();
click('mode-edit');    await new Promise(r=>setTimeout(r,120));
const editBar = bar();
click('page-offset');  await new Promise(r=>setTimeout(r,120));
const offsetTitle = document.querySelector('.pane-main h3')?.textContent;
click('page-position');await new Promise(r=>setTimeout(r,120));

// which pane is white?
const active = [...document.querySelectorAll('.pane.active')].map(e=>e.className.match(/pane-(\w+)/)[1]);

JSON.stringify({before, afterJog, memBar, editBar, offsetTitle, active,
  increment: document.querySelector('.pane-timers pre').textContent.match(/INC\s+([\d.]+)/)?.[1]}, null, 1)

const prog = `(O1234 FACE AND SLOT)
G21 G90 G54
G0 X0 Y0 Z25.
M3 S2400
G0 X-5. Y10.
G1 Z-1. F300
G1 X85. F900
G1 Y30.
G1 X-5.
G1 Y50.
G1 X85.
G0 Z25.
M5
M30`;
const dt = new DataTransfer();
dt.items.add(new File([prog], 'O1234.nc', { type: 'text/plain' }));
const inp = document.getElementById('file');
inp.files = dt.files;
inp.dispatchEvent(new Event('change'));
await new Promise(r => setTimeout(r, 300));

