/** Where the machine will be once everything currently queued has run. */
plannedEnd () {
  for (let i = this.queue.length - 1; i >= 0; i--) {
    if (this.queue[i].target) return this.queue[i].target
  }
  return this.current?.target ?? this.mpos
}

